n',$product->id) }}">@csrf<input class="mini-input" type="number" name="quantity" min="1" value="1"><button class="mini-btn in">Stock in</button></form><form method="POST" action="{{ route('products.stockOut',$product->id) }}">@csrf<input class="mini-input" type="number" name="quantity" min="1" value="1"><button class="mini-btn out">Stock out</button></form></div>@endif</td></tr>@empty<tr><td colspan="7" class="center muted">No products found.</td></tr>@endforelse</tbody></table></div></div><div class="panel"><div class="panel-head"><h2>Recent stock activity</h2><span class="muted">Latest 8 movements</span></div><div class="activity-list">@forelse($recentMovements as $move)<div class="activity"><span class="activity-dot {{ $move->type==='STOCK_OUT'?'out':'in' }}"></span><div><strong>{{ $move->type }}</strong> · {{ $move->product->product_name }} <small>{{ $move->quantity }} units · balance {{ $move->balance_after }}</small></div><time>{{ $move->created_at->diffForHumans() }}</time></div>@empty<p class="muted">No stock movements recorded yet.</p>@endforelse</div></div>@endsection
